public static InStream create(String name,
                                ByteBuffer input,
                                CompressionCodec codec,
                                int bufferSize) throws IOException {
    if (codec == null) {
      return new UncompressedStream(name, input);
    } else {
      return new CompressedStream(name, input, codec, bufferSize);
    }
  }
